router21.post("/youtube/live/chat", async (req, res, next2) => {
  try {
    const authHeader = String(req.headers.authorization ?? "").trim();
    const accessToken = authHeader.toLowerCase().startsWith("bearer ") ? authHeader.slice(7).trim() : "";
    if (!accessToken) {
      res.status(401).json({
        error: "youtube_oauth_required",
        message: "Google YouTube access token required to send live chat.",
        reason: "authRequired"
      });
      return;
    }
    const liveChatId = String(req.body?.liveChatId ?? "").trim();
    const messageText = String(req.body?.messageText ?? "").trim();
    if (!liveChatId) {
      res.status(400).json({ error: "liveChatId required" });
      return;
    }
    if (!messageText) {
      res.status(400).json({ error: "messageText required" });
      return;
    }
    if (messageText.length > 200) {
      res.status(400).json({ error: "message_too_long", message: "Max 200 characters." });
      return;
    }
    const upstream = await fetch(
      "https://www.googleapis.com/youtube/v3/liveChat/messages?part=snippet",
      {
        method: "POST",
        headers: {
          authorization: `Bearer ${accessToken}`,
          "content-type": "application/json"
        },
        body: JSON.stringify({
          snippet: {
            liveChatId,
            type: "textMessageEvent",
            textMessageDetails: { messageText }
          }
        })
      }
    );
    const body = await upstream.json();
    if (!upstream.ok) {
      res.status(upstream.status).json({
        error: "youtube_live_chat_send_failed",
        message: body.error?.message ?? upstream.statusText,
        reason: body.error?.errors?.[0]?.reason ?? null
      });
      return;
    }
    res.json({
      id: body.id ?? `sent-${Date.now()}`,
      message: body.snippet?.displayMessage?.trim() || body.snippet?.textMessageDetails?.messageText?.trim() || messageText
    });
  } catch (error45) {
    next2(error45);
  }
});
