function relatedSearchQuery(title) {
  const cleaned = title.replace(/\[[^\]]*]/g, " ").replace(/\([^)]*\)/g, " ").replace(/official\s*(music\s*)?(video|audio|mv)/gi, " ").replace(/\s+/g, " ").trim();
  return (cleaned || title).slice(0, 96);
}
